b.constraint('observer_existing_workspace',['graph_function'],'Publish executive observer as a GraphFunction over an existing declared target workspace and work, expressed through environment, Context locator/digest and AssetSurface required-context truth. Create no observer-specific workspace, graph, frame, replay or continuation topology.',[(0,62,67)],conditions=['GraphFunction represents an ABG executive observer.'])
b.constraint('node_type_noncallability',['node_type'],'Preserve node-type identity, contract, publication semantics and noncallability. Neither realization nor publication mints GraphFunction identity or runtime effects. Job/public-start binding, runtime-registry callable selection, graph-call opening and invocation assertion reject node-type entries as callables.',[(0,69,80)])
b.constraint('vector_structure_and_governance',['graph_vector'],'A vector has one source node or ordered source tuple and one target. Operators/evaluators declare local construction/convergence, rule local constraint, and allows_subwork bounded capability. declarations canonically describes one invariant transition; preserve inspectability/replayability across publication, serialization and interpretation. Work entry and Jobs never target bare vectors beneath published callables.',[(3,21,31)])
b.latitude('vector_declaration_variation',['graph_vector'],['Declare transition description, dispatch/evaluation/escalation policy, deterministic proof, closure contract, assurance/other hooks and opaque config.','Declare subordinate evaluation-scope topology for segment, dimension-cell, fold or relation within the vector and selected composition.'],['Promoting evaluation segments/cells/folds/relations into public execution, semantic Job targets or new topology objects.'],[(3,27,27),(3,53,53)])
b.constraint('vector_local_precedence',['graph_vector'],'When present, vector traversal-modulation qualifier has highest hook precedence and cannot be overridden by GraphFunction/Role defaults. Per-edge strategy is declared at abg.traversal_strategy; ABG carries its selection as runtime truth but the label remains descriptive Product metadata.',[(3,33,35)],conditions=['A traversal-modulation qualifier is present.'])
b.constraint('vector_temporal_contract',['graph_vector'],'Single-boundary temporal eligibility may attach only through live canonical abg.temporal_constraint hook_ref with config constraint_ref, operator, not_before_ref, optional deadline_ref, schedule_policy_ref, timer_provider_ref and deadline_breach_action. Eligibility, breach pressure and policy consequences act only through ABG replay; vectors stay nonpublic. Reject alternate temporal keys as live authority.',[(3,37,37)],conditions=['A temporal constraint governs one traversal boundary.'])
b.constraint('edge_assurance_contract_scope',['graph_vector'],'Optional abg.edge_assurance_contract hook/config describes scoped target outcome, authority, obligation bindings, F_P transform/eval, admissible evidence, gain, metric, closure decision, residual pressure, continuation, composition law, cheap checks and policy. Vector-local assurance has highest precedence; GraphFunction, Job, Role, Module and installed defaults cannot override it. If no edge assurance function is declared, automated closure is not licensed: default is F_H by absentia, with any human closure/continuation edge-scoped and ABG-replay-visible.',[(3,39,43)],exceptions=['Wider/default declarations can supply absent assurance contracts, not override vector-local contracts.'])
b.constraint('effective_target_contract',['graph_vector','target_carrier_contract'],'Every output surface requires an effective binding. Vector-local binding has highest precedence; absent Product-specific binding resolves from visible GTL config defaults, never code constants, prompts, parser conventions or null. Malformed present declarations or missing/malformed defaults fail closed.',[(3,45,45)])
b.constraint('target_contract_required_fields',['target_carrier_contract'],'At minimum bind target node, output surface, carrier family/kind, envelope contract, nested payload path, required/fixed protocol/Worker-fillable fields, literal/enum domains, schema/admission references, payload-ledger and edge-assurance bindings, handoff projection, construction template, replay digest and materialization policies, closure precondition and test-case generation references.',[(3,47,47)])
b.constraint('vector_composition_binding',['graph_vector'],'Closure-capable, mixed-regime, optimized or construction-substrate traversal requires effective abg.fn_composition. Vector-local selection wins over GraphFunction/Job/Role/Module/visible defaults. A vector-local composition is host-bound and fails closed if host vector, source node, target node, target schema, target-carrier or assurance contract reference mismatches the effective boundary.',[(3,49,51)],conditions=['Traversal is closure-capable, mixed-regime, optimized or construction-substrate.'])
b.constraint('traversal_unit_structural_scope',['graph_vector'],'GraphVector<A,B> is a TraversalUnit<A,B> structural boundary only under a selected parent GraphFunction execution and abg.fn_composition. This notation creates no bare-vector public start/Job target, new topology or runtime controller.',[(3,55,55)])
b.relation('vector_target_binding','requires_effective_contract','graph_vector','target_carrier_contract','Every vector output uses its local or visible-default target carrier contract with fail-closed resolution.',[(3,45,47)],True)
b.constraint('fan_out_declaration_identity',['fan_out_relation'],'Explicit element/input-vector/output-vector relation admission joins vector schemas to member contracts; schema strings alone do not admit types. Wholly successful application preserves input cardinality and stable ordinal, pairing output i only with input i. Native authoring, serialization, raw admission and validation preserve the first-class relation; no inference from names, labels, tags, shared node identity or hidden cardinality.',[(6,16,26)],conditions=['Cardinality/ordinal preservation applies to a wholly successful vector application.'])
