b.latitude('harvest_and_realization_latitude',['higher_order_combinator','fan_out_relation'],['Expose evaluator/candidate/other harvested vectors over a contract boundary while leaving merge semantics outside GTL.','Serial execution is a lawful realization of fan_out pointwise batch projection.'],['Inferring concurrency from fan_out or C.batch.','Using informal zoom/fold terms to authorize hidden heuristics, unowned registers or duplicate algebra.'],[(6,40,46),(6,48,56)])
b.constraint('zoom_terms_need_owned_law',['higher_order_combinator'],'Zoom-in/out/fold terminology must resolve to existing lawful operations or be repriced into new requirements before implementation.',[(6,42,46)])
b.constraint('fan_out_pointwise_batch',['fan_out_relation'],'Runtime realization projects one admitted nonempty ordered input vector to one C.batch task per input member. Each preserves exact child GraphFunction, member I/O contracts, original zero-based ordinal, lineage and enclosing C program/stage/fibre/arm/composition authority. Batch reference is grouping only, never call, scheduler or closure authority.',[(6,48,56)])
b.constraint('fan_out_atomic_output_admission',['fan_out_relation'],'Admit output vector only if every task completes exactly once under the declared output-member contract and rows conserve cardinality/ordinal. Completion time cannot change attribution/order. A blocked, held, malformed or runtime-failed member preserves completed evidence, names stopping ordinal and unstarted tasks, admits no output vector and permits no downstream fan-in or graph-success projection for that invocation.',[(6,58,65)])
b.constraint('fan_in_complete_vector',['fan_in_relation'],'Consume one complete admitted vector matching declared node/contract, preserving basis, cardinality, ordinals, member attribution and application lineage; invoke the exact reducer GraphFunction once. Incomplete, mismatched, duplicated or reordered vectors stop before reducer traversal. Only admitted reducer completion becomes synthesized result; blocked/held/malformed/runtime-failed reducer truth remains non-success.',[(6,67,74)])
b.constraint('higher_order_runtime_authority',['higher_order_combinator'],'Runtime binding derives from exact selected catalog entry, admitted Module, structural HOF or GraphFunction-application declaration, and opaque callable/node identities. Names, tags, fixed cardinality, promise completion order and caller semantic defaults provide no authority. HoG traverses admitted HOF/C; ABG owns task frames, traversal evidence, result admission and failure. Product effects still need separately admitted traversal/capability gates.',[(6,76,84)])
